mapper.update:
DECLARE
    v_count NUMBER;
    v_nullable VARCHAR2(1);
BEGIN
    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'USER_NOTICES' AND COLUMN_NAME = 'ALERT_TYPE';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES ADD (ALERT_TYPE VARCHAR2(50) DEFAULT ''NOTICE'' NOT NULL)';
    END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'USER_NOTICES' AND COLUMN_NAME = 'TARGET_TYPE';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES ADD (TARGET_TYPE VARCHAR2(50))';
    END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'USER_NOTICES' AND COLUMN_NAME = 'TARGET_ID';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES ADD (TARGET_ID NUMBER)';
    END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'USER_NOTICES' AND COLUMN_NAME = 'TITLE';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES ADD (TITLE VARCHAR2(300))';
    END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'USER_NOTICES' AND COLUMN_NAME = 'CONTENT';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES ADD (CONTENT VARCHAR2(1000))';
    END IF;

    SELECT COUNT(*) INTO v_count FROM USER_TAB_COLUMNS WHERE TABLE_NAME = 'USER_NOTICES' AND COLUMN_NAME = 'LINK_URL';
    IF v_count = 0 THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES ADD (LINK_URL VARCHAR2(500))';
    END IF;

    SELECT NULLABLE INTO v_nullable
      FROM USER_TAB_COLUMNS
     WHERE TABLE_NAME = 'USER_NOTICES'
       AND COLUMN_NAME = 'NOTICE_ID';

    IF v_nullable = 'N' THEN
        EXECUTE IMMEDIATE 'ALTER TABLE USER_NOTICES MODIFY (NOTICE_ID NULL)';
    END IF;
END;

UPDATE USER_NOTICES
   SET IS_READ = 'Y'
 WHERE ALARM_ID = #{alarmId}
